// Normalize the form answers once so every later node reads the same field
// names, and derive the pieces the writer needs rather than asking for them.
const f = $json;

function get(label) {
  return String(f[label] === undefined || f[label] === null ? '' : f[label]).trim();
}

const contactEmail = get('Contact Email').toLowerCase();
const contactName = get('Contact Full Name');
const website = get('Company Website');

if (!contactEmail.includes('@') || contactEmail.split('@')[1].indexOf('.') < 1) {
  throw new Error('That contact email does not look valid: ' + contactEmail);
}

// First name only, because "Dear Priya Raman," reads like a mail merge.
const firstName = contactName.split(/\s+/)[0] || 'there';

// Prefer the website domain, fall back to the email domain.
let domain = website.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
if (!domain) domain = contactEmail.split('@')[1];

return [{
  json: {
    companyName: get('Company Name'),
    companyDescription: get('What does the company do'),
    industry: get('Industry'),
    website: website,
    domain: domain,
    contactName: contactName,
    firstName: firstName,
    contactEmail: contactEmail,
    hook: get('Why are you reaching out now'),
    senderName: get('Your Name'),
    senderCompany: get('Your Company'),
    senderOffer: get('What you help companies with'),
    rowKey: contactEmail,
    submittedAt: new Date().toISOString(),
  },
}];

