// Three variants come back from the writer. Each one is scored against the
// rules that actually get cold email delivered and read, then the best one
// wins. Scoring here rather than in the prompt means the result is repeatable
// and the reasons are visible to the person reviewing the draft.
const prospect = $('Clean Prospect Fields').first().json;
const out = $json.output || {};
const variants = Array.isArray(out.variants) ? out.variants : [];

const SPAM_WORDS = ['free', 'guarantee', 'guaranteed', 'risk free', 'act now', 'limited time',
  'click here', 'buy now', 'cheap', 'discount', 'exclusive deal', 'urgent', 'winner',
  'no obligation', 'cash', 'double your', 'skyrocket', 'game changer', 'revolutionary'];

const TIRED_OPENERS = ['i hope this email finds you', 'i hope you are doing well',
  'i wanted to reach out', 'i am reaching out', 'quick question', 'just checking in',
  'hope all is well', 'allow me to introduce'];

function textOf(html) {
  return String(html || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
}

function score(v) {
  const subject = String(v.subject || '').trim();
  const body = textOf(v.bodyHtml);
  const lower = (subject + ' ' + body).toLowerCase();
  const words = body ? body.split(' ').length : 0;
  const subjectWords = subject ? subject.split(/\s+/).length : 0;
  const links = (String(v.bodyHtml || '').match(/<a\s/gi) || []).length;

  let points = 100;
  const notes = [];

  // Subject line: short enough to survive a phone inbox, long enough to say something.
  if (subjectWords < 3) { points -= 15; notes.push('Subject is too short to say anything'); }
  else if (subjectWords > 9) { points -= 12; notes.push('Subject runs to ' + subjectWords + ' words and will be cut off on mobile'); }
  if (subject === subject.toUpperCase() && subject.length > 6) { points -= 10; notes.push('Subject is in capitals'); }
  if (/[!?]{1,}/.test(subject)) { points -= 6; notes.push('Subject uses an exclamation or question mark'); }

  // Body length: long enough to earn a reply, short enough to be read.
  if (words < 55) { points -= 12; notes.push('Body is only ' + words + ' words and reads as thin'); }
  else if (words > 140) { points -= 14; notes.push('Body is ' + words + ' words, which is long for a first touch'); }

  // Spam triggers.
  const hits = SPAM_WORDS.filter(function (w) { return lower.indexOf(w) !== -1; });
  if (hits.length) { points -= Math.min(30, hits.length * 8); notes.push('Spam trigger words: ' + hits.join(', ')); }

  // Openers every prospect has read a hundred times.
  const tired = TIRED_OPENERS.filter(function (w) { return lower.indexOf(w) !== -1; });
  if (tired.length) { points -= tired.length * 9; notes.push('Worn out phrasing: ' + tired.join(', ')); }

  // Personalisation: the prospect should appear by name and by company.
  if (lower.indexOf(prospect.firstName.toLowerCase()) === -1) { points -= 12; notes.push('The contact first name is missing'); }
  if (prospect.companyName && lower.indexOf(prospect.companyName.toLowerCase()) === -1) {
    points -= 10; notes.push('The company name is never mentioned');
  }

  // Links: one is a call to action, several is a pitch deck.
  if (links > 1) { points -= (links - 1) * 8; notes.push(links + ' links in a first email'); }

  // A question invites a reply.
  if (body.indexOf('?') === -1) { points -= 8; notes.push('No question, so there is nothing easy to reply to'); }

  // Unresolved template placeholders are the classic mail merge failure.
  if (/\[[^\]]+\]|\{\{|[A-Z]{3,}_[A-Z]{3,}/.test(subject + ' ' + String(v.bodyHtml || ''))) {
    points -= 25; notes.push('An unfilled placeholder is still in the text');
  }

  return {
    angle: String(v.angle || 'Unnamed angle'),
    subject: subject,
    bodyHtml: String(v.bodyHtml || ''),
    words: words,
    subjectWords: subjectWords,
    links: links,
    score: Math.max(0, Math.min(100, points)),
    notes: notes,
  };
}

const scored = variants.map(score).sort(function (a, b) { return b.score - a.score; });

if (!scored.length) {
  throw new Error('The writer returned no usable variants. Open the writer node and check the model response.');
}

const winner = scored[0];
const followUp = out.followUp || {};

return [{
  json: Object.assign({}, prospect, {
    chosenAngle: winner.angle,
    subject: winner.subject,
    bodyHtml: winner.bodyHtml,
    deliverabilityScore: winner.score,
    deliverabilityNotes: winner.notes,
    wordCount: winner.words,
    followUpSubject: String(followUp.subject || 'Following up on my note'),
    followUpBodyHtml: String(followUp.bodyHtml || ''),
    scoreboard: scored.map(function (s) {
      return { angle: s.angle, score: s.score, subject: s.subject, issues: s.notes.length };
    }),
    rejectedVariants: scored.slice(1),
  }),
}];

// Two rows, not one: the first touch and the follow up that is due later. The
// sheet becomes the sequence, so a second workflow or a person can pick up
// step two on its send date without this workflow staying alive.
const d = $('Score Deliverability').first().json;
const draftStatus = $json.id ? 'Draft created' : 'Draft not created';

function addBusinessDays(days) {
  const date = new Date();
  let added = 0;
  while (added < days) {
    date.setDate(date.getDate() + 1);
    const day = date.getDay();
    if (day !== 0 && day !== 6) added += 1;
  }
  return date.toISOString().slice(0, 10);
}

const approved = d.deliverabilityScore >= 70;
const today = new Date().toISOString().slice(0, 10);

const rows = [
  {
    rowKey: d.contactEmail + ' | step 1',
    step: 'Step 1 cold email',
    subject: (approved ? '' : '[REVIEW] ') + d.subject,
    bodyHtml: d.bodyHtml,
    sendOn: today,
    status: approved ? 'Draft ready to send' : 'Needs a rewrite before sending',
  },
  {
    rowKey: d.contactEmail + ' | step 2',
    step: 'Step 2 follow up',
    subject: d.followUpSubject,
    bodyHtml: d.followUpBodyHtml,
    sendOn: addBusinessDays(4),
    status: 'Queued',
  },
];

return rows.map(function (r) {
  return {
    json: {
      rowKey: r.rowKey,
      step: r.step,
      companyName: d.companyName,
      contactName: d.contactName,
      contactEmail: d.contactEmail,
      domain: d.domain,
      industry: d.industry,
      chosenAngle: d.chosenAngle,
      subject: r.subject,
      bodyHtml: r.bodyHtml,
      deliverabilityScore: d.deliverabilityScore,
      issues: (d.deliverabilityNotes || []).join('; '),
      sendOn: r.sendOn,
      status: r.status,
      draftStatus: draftStatus,
      createdAt: d.submittedAt,
    },
  };
});

